import react from "@vitejs/plugin-react";
import { defineConfig } from "vitest/config";

export default defineConfig({
  plugins: [react()],
  test: {
    environment: "jsdom",
    setupFiles: ["./src/test/setup.ts"],
    clearMocks: true,
    restoreMocks: true,
    fileParallelism: false,
  },
});

import "@testing-library/jest-dom/vitest";

class ResizeObserverStub implements ResizeObserver {
  disconnect() {}
  observe() {}
  unobserve() {}
}

Object.defineProperty(globalThis, "ResizeObserver", {
  configurable: true,
  value: ResizeObserverStub,
});

if (!globalThis.PointerEvent) {
  if (typeof MouseEvent !== "undefined") {
    Object.defineProperty(globalThis, "PointerEvent", {
      configurable: true,
      value: MouseEvent,
    });
  }
}

// jsdom does not currently expose DragEvent. Testing Library falls back to a plain Event in
// that case, which silently drops MouseEvent coordinates such as clientX/clientY. Use the
// MouseEvent constructor as the closest available browser primitive so drag/drop tests exercise
// the same edge calculations as the real WebView. Testing Library supplies dataTransfer itself.
if (!globalThis.DragEvent) {
  if (typeof MouseEvent !== "undefined") {
    Object.defineProperty(globalThis, "DragEvent", {
      configurable: true,
      value: MouseEvent,
    });
  }
}

if (!globalThis.requestAnimationFrame) {
  Object.defineProperty(globalThis, "requestAnimationFrame", {
    configurable: true,
    value: (callback: FrameRequestCallback) => globalThis.setTimeout(() => callback(performance.now()), 0),
  });
}

if (!globalThis.cancelAnimationFrame) {
  Object.defineProperty(globalThis, "cancelAnimationFrame", {
    configurable: true,
    value: (handle: number) => globalThis.clearTimeout(handle),
  });
}

const { beforeEach: setupBeforeEach } = await import("vitest");
const { clearHmrWorkspaceState } = await import("../state/hmrWorkspaceState");

setupBeforeEach(() => {
  clearHmrWorkspaceState();
});

> I read this as research and test strategy formulation - inspecting UI test fixtures, TerminalPane, terminalHostManager, and xterm/fit/resize APIs to determine a deterministic failing-first test strategy for the one-line reactivation scroll offset.

### 1. UI Package & Test Setup Inspection

* **Test Framework & Harness**:
  * Runner: **Vitest v3.0.5** (`ui/vitest.config.ts`) running in `jsdom` with `setupFiles: ["./src/test/setup.ts"]`.
  * Package manager: **Bun**.
  * React Testing: `@testing-library/react` v16.2.0.
* **Key Source Files**:
  * `ui/src/components/TerminalPane.tsx`: Manages React lifecycle, visibility registration, font-ready fit trigger, and DOM element attachment.
  * `ui/src/lib/terminalHostManager.ts`: Manages session instances, LRU caching, `markSessionVisible` / `markSessionInactive`, `reset()`, and re-subscribing output.
  * `ui/src/lib/terminalInstanceFactory.ts`: Instantiates `@xterm/xterm`, loads addons (`FitAddon`, `SearchAddon`, `Unicode11Addon`), and binds `ResizeObserver` with `requestAnimationFrame`.
  * `ui/src/lib/terminalOutputScheduler.ts`: Batches incoming PTY chunks at animation-frame cadence and writes to `terminal.write(...)`.
  * `ui/src/lib/terminalHostManagerTestHelper.ts`: Houses test mocks (`MockTerminal`, `MockFitAddon`, `setupTerminalHostTestEnv`, `flushAnimationFrames`).

---

### 2. Relevant APIs & Root Cause Analysis

* **xterm.js Buffer & Scroll APIs**:
  * `terminal.buffer.active.baseY`: Number of lines in scrollback (i.e. zero-based index of top visible row when at bottom).
  * `terminal.buffer.active.viewportY`: Current visible top line index in the buffer.
  * `terminal.buffer.active.length`: Total buffer lines (`baseY + terminal.rows`).
  * `terminal.buffer.active.cursorY`: Active cursor row in viewport (`0` to `rows - 1`).
  * `terminal.scrollToBottom()` / `terminal.scrollToLine(line: number)`.
  * `terminal.write(data: string, callback?: () => void)`: Completes ANSI parsing asynchronously and executes `callback`.
  * `terminal.resize(cols: number, rows: number)`: Triggers buffer reflow and recalculates `baseY` / `viewportY`.
  * `terminal.reset()`: Resets `baseY = 0` and `viewportY = 0`.
* **FitAddon & ResizeObserver APIs**:
  * `fitAddon.fit()`: Measures host container and invokes `terminal.resize(cols, rows)`.
  * `ResizeObserver`: Dispatches container size change, scheduling `resize()` on `requestAnimationFrame`.
* **Ordering Conflict on Reactivation**:
  1. On reactivation, `terminalHostManager.markSessionVisible()` immediately calls `inst.terminal.reset()`, setting `baseY = 0` and `viewportY = 0`.
  2. `attachScheduledOutputSubscription()` receives the backlog and queues it for an animation frame flush.
  3. Meanwhile, DOM mounting triggers `document.fonts.ready` / `ResizeObserver` -> `fitAddon.fit()`, which resizes `rows` (e.g. from default 24 to container row count 30).
  4. If viewport scroll restoration or auto-bottom following happens **before** `terminal.write()` flushes and parses the backlog, `viewportY` is clamped to `0`. If `fitAddon.fit()` runs **after** `terminal.write()` has established `baseY`, reflow changes `baseY` by $\Delta\text{rows}$, leaving `viewportY` offset by exactly 1 row (`viewportY === baseY - 1`) when trailing newlines/cursor wrapping occur.

---

### 3. Feasibility of Unit/Integration Test

A deterministic unit/integration test in Vitest **can prove the correct ordering** between viewport scroll restoration, `fitAddon.fit()`, `ResizeObserver`, and batched terminal writes without desktop automation.

By enriching `MockTerminal` to track buffer geometry (`baseY`, `viewportY`, `rows`, `length`) and write completion callbacks:
* The test controls `requestAnimationFrame` flushes via `flushAnimationFrames()`.
* It verifies whether viewport scroll restoration waits for both `fitAddon.fit()` and the `terminal.write` backlog completion callback.

