      this.buffer.active.length += lines;
      this.buffer.active.baseY = Math.max(0, this.buffer.active.length - this.rows);
      // Auto-follow if previously at bottom before write
      if (this.buffer.active.viewportY === this.buffer.active.baseY - lines) {
        this.buffer.active.viewportY = this.buffer.active.baseY;
      }
      cb?.();
    });
